import data from "./springs.json";
import { smart } from "./typo.mjs";
import { SITE_URL } from "./site";

// Generated by scripts/site/springs.mjs from core/motion/springs.js. Each preset's stiffness and damping
// come from the library's own source or docs; `source` and `original` say where, `conversion` says how.

export type Related = { slug: string; name: string; gap: number };
export type Spring = {
  slug: string;
  lib: string;
  name: string;
  short: string;
  k: number;
  d: number;
  mass: number;
  zeta: number;
  omega: number;
  period: number | null;
  settle: number;
  ms: number;
  overshoot: number;
  overshootAt: number;
  crossings: number;
  t50: number;
  t90: number;
  peakSpeed: number;
  y: number[];
  vel: number[];
  linear: string;
  points: number;
  linearWorst: number;
  source: { version: string; file?: string; url: string | null };
  original: string;
  conversion: string | null;
  note: string;
  related: Related[];
};
export type Library = { id: string; label: string; intro: string };

export const SPRINGS = (data.springs as Spring[]).map((s) => ({ ...s, note: smart(s.note) }));
export const LIBRARIES = data.libraries as Library[];
export const THRESHOLD_PERCENT = data.threshold * 100;

export const springBySlug = (slug: string) => SPRINGS.find((s) => s.slug === slug) ?? null;
export const springsIn = (lib: string) => SPRINGS.filter((s) => s.lib === lib);
export const libraryOf = (s: Spring) => LIBRARIES.find((l) => l.id === s.lib)!;
export const isHouse = (s: Spring) => s.lib === "vawe";

export const SPRINGS_TITLE = "Spring animation presets as CSS linear(): react-spring, Motion, SwiftUI, Compose | vawe";
export const SPRINGS_DESCRIPTION = `${SPRINGS.length} spring presets as CSS linear(): stiffness, damping, settle time and overshoot for react-spring, Motion, SwiftUI, Compose, Material 3 and vawe.`;

export const PUBLISHED = "2026-11-03";

const trim = (n: number) => String(n);
export const kText = (s: Spring) => trim(s.k);
export const dText = (s: Spring) => trim(s.d);
export const secText = (s: Spring) => `${s.settle} s`;
export const overshootText = (s: Spring) => `${s.overshoot}%`;
export const camelOf = (slug: string) => slug.replace(/-([a-z])/g, (_, c: string) => c.toUpperCase());

export function characterOf(s: Spring) {
  if (s.zeta < 0.95) return "underdamped";
  if (s.zeta <= 1.05) return "about critically damped";
  return "overdamped";
}

export function pageTitle(s: Spring) {
  const full = `${s.name}: CSS linear() spring, stiffness ${s.k} damping ${s.d} | vawe`;
  return full.length <= 78 ? full : `${s.name}: stiffness ${s.k}, damping ${s.d} spring | vawe`;
}

export function summary(s: Spring) {
  const shape =
    s.overshoot > 0
      ? `It passes the end value by up to ${s.overshoot}% at ${s.overshootAt} s and crosses it ${s.crossings} ${s.crossings === 1 ? "time" : "times"}.`
      : "It never passes the end value.";
  return `Stiffness ${s.k}, damping ${s.d} and mass 1 give a damping ratio of ${s.zeta}, so the spring is ${characterOf(s)}. It settles to within ${THRESHOLD_PERCENT}% in ${s.settle} s. ${shape}`;
}

export function pageDescription(s: Spring) {
  const lead = `${s.name} as a CSS linear() spring: stiffness ${s.k}, damping ${s.d}, settles in ${s.settle} s`;
  const text = `${lead}, ${s.overshoot > 0 ? `overshoots ${s.overshoot}%` : "no overshoot"}. Copy the CSS and the Web Animations line.`;
  return text.length <= 160 ? text : `${lead}. Copy the CSS and the Web Animations line.`;
}

export const cssText = (s: Spring) => `transition: translate ${s.ms}ms ${s.linear};`;

export function waapi(s: Spring) {
  return `el.animate({ translate: ['0 0', '240px 0'] }, { duration: ${s.ms}, easing: '${s.linear}', fill: 'both' });`;
}

export function vaweCode(s: Spring) {
  const source = isHouse(s) ? `const { k, d } = SPRINGS.${s.short};` : `const k = ${s.k}, d = ${s.d};`;
  const imports = isHouse(s) ? "SPRINGS, spring, springDuration, springLinear" : "spring, springDuration, springLinear";
  return `import { ${imports} } from '../../core/motion/springs.js';

${source}

// per-frame code (window.seek, vawe.onFrame): t is seconds since the move starts
const x = 240 * spring(t, k, d);

// CSS and Web Animations: ${s.ms} ms, the linear() string above
el.animate(
  { translate: ['0 0', '240px 0'] },
  { duration: springDuration(k, d) * 1000, easing: springLinear(k, d), fill: 'both' },
);`;
}

// The shape the easing charts take: progress against time on 0..1 of the settle time.
export function curveOf(s: Spring) {
  return { name: s.name, y: s.y, vel: s.vel, t50: s.t50 / s.settle, t90: s.t90 / s.settle, peakSpeed: s.peakSpeed };
}

const ORG = { "@type": "Organization", name: "vawe", url: SITE_URL };

export function techArticleSchema(s: Spring) {
  return {
    "@context": "https://schema.org",
    "@type": "TechArticle",
    headline: pageTitle(s).replace(/ \| vawe$/, ""),
    description: pageDescription(s),
    url: `${SITE_URL}/springs/${s.slug}`,
    inLanguage: "en",
    proficiencyLevel: "Beginner",
    datePublished: PUBLISHED,
    dateModified: PUBLISHED,
    author: ORG,
    publisher: ORG,
    about: "Spring animation preset as a CSS linear() easing",
  };
}

export function itemListSchema() {
  return {
    "@context": "https://schema.org",
    "@type": "ItemList",
    name: "Spring animation presets as CSS linear()",
    numberOfItems: SPRINGS.length,
    itemListElement: SPRINGS.map((s, i) => ({ "@type": "ListItem", position: i + 1, name: s.name, url: `${SITE_URL}/springs/${s.slug}` })),
  };
}
